WITH flattened_attrs AS (SELECT id, log_ts, level, latency_ms, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, COALESCE(context['version'], 'unknown') AS version_or_default, COALESCE(context['region'], 'unknown') AS region_or_default FROM app_logs WHERE level = 'WARN') SELECT id, log_ts, level, latency_ms, payload_json, duration_sec, user_id, duration_text, version_or_default, region_or_default, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY level), 4) AS latency_ms_share, NTILE(4) OVER (PARTITION BY level ORDER BY latency_ms, id) AS latency_ms_bucket FROM flattened_attrs
